import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const checkMode = process.argv.includes("--check");

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(scriptDir, "..");

const header = `// AUTO-GENERATED FILE. DO NOT EDIT.
// Source of truth:
// - src/shared/structuredOutputSchema.ts
// - src/shared/structuredOutputValidator.ts
// Generated by: scripts/sync-structured-output-contract.mjs
`;

const targets = [
  {
    source: path.join(repoRoot, "src", "shared", "structuredOutputSchema.ts"),
    dest: path.join(
      repoRoot,
      "webview",
      "shared",
      "src",
      "chat",
      "lib",
      "generated",
      "structuredOutputSchema.ts",
    ),
  },
  {
    source: path.join(
      repoRoot,
      "src",
      "shared",
      "structuredOutputValidator.ts",
    ),
    dest: path.join(
      repoRoot,
      "webview",
      "shared",
      "src",
      "chat",
      "lib",
      "generated",
      "structuredOutputValidator.ts",
    ),
  },
];

function normalize(value) {
  return value.replace(/\r\n/g, "\n");
}

function toGeneratedContents(sourceContents) {
  return `${header}\n${normalize(sourceContents)}`;
}

function relativeFromRepo(filePath) {
  return path.relative(repoRoot, filePath).replace(/\\/g, "/");
}

const outOfSyncFiles = [];
const writtenFiles = [];

for (const target of targets) {
  const sourceContents = fs.readFileSync(target.source, "utf8");
  const nextContents = toGeneratedContents(sourceContents);

  const existingContents = fs.existsSync(target.dest)
    ? fs.readFileSync(target.dest, "utf8")
    : null;

  if (existingContents !== nextContents) {
    if (checkMode) {
      outOfSyncFiles.push(relativeFromRepo(target.dest));
      continue;
    }

    fs.mkdirSync(path.dirname(target.dest), { recursive: true });
    fs.writeFileSync(target.dest, nextContents, "utf8");
    writtenFiles.push(relativeFromRepo(target.dest));
  }
}

if (checkMode && outOfSyncFiles.length > 0) {
  console.error("Out-of-sync files detected:");
  outOfSyncFiles.forEach((file) => {
    console.error(`- ${file}`);
  });
  process.exit(1);
}

if (checkMode) {
  console.log("Structured output contract is in sync.");
} else if (writtenFiles.length > 0) {
  console.log("Synced structured output contract files:");
  writtenFiles.forEach((file) => {
    console.log(`- ${file}`);
  });
} else {
  console.log("Structured output contract files are already up to date.");
}
